    "code": "import numpy as np\nimport matplotlib.pyplot as plt\n\n# --- 1. נתונים: שני ענני נקודות גאוסיאניים (פרק 9) ---\nnp.random.seed(0)\nn = 200\nX0 = np.random.randn(n, 2) + np.array([-2.0, -1.0])   # מחלקה 0\nX1 = np.random.randn(n, 2) + np.array([2.0, 1.5])     # מחלקה 1\nX = np.vstack([X0, X1])                    # (400, 2)\ny = np.concatenate([np.zeros(n), np.ones(n)])\n\n# ערבוב ופיצול לאימון ובדיקה\nidx = np.random.permutation(len(y))\nX, y = X[idx], y[idx]\nX_train, y_train = X[:300], y[:300]\nX_test, y_test = X[300:], y[300:]\n\n# --- 2. נרמול לפי סט האימון בלבד (סעיף 9.4) ---\nmu, sd = X_train.mean(axis=0), X_train.std(axis=0)\nX_train = (X_train - mu) / sd\nX_test = (X_test - mu) / sd\n\n# --- 3. המודל ---\ndef sigmoid(z):\n    return 1 / (1 + np.exp(-z))\ndef predict_proba(X, w, b):\n    return sigmoid(X @ w + b)               # (n,2) @ (2,) → (n,)\n\ndef loss_fn(p, y):\n    eps = 1e-12                             # מונע לוגריתם של אפס\n    return -np.mean(y * np.log(p + eps) + (1 - y) * np.log(1 - p + eps))\n\n# --- 4. לולאת אימון (פרק 8) ---\nw = np.zeros(2)\nb = 0.0\nlr = 0.5\nhistory = []\nfor epoch in range(200):\n    p = predict_proba(X_train, w, b)                  # מעבר קדימה\n    history.append(loss_fn(p, y_train))\n    error = p - y_train                               # הנגזרת לפי z\n    grad_w = X_train.T @ error / len(y_train)         # מעבר לאחור\n    grad_b = error.mean()\n    w -= lr * grad_w                                  # עדכון\n    b -= lr * grad_b\n\n# --- 5. הערכה ---\ntest_pred = predict_proba(X_test, w, b) >= 0.5\naccuracy = np.mean(test_pred == y_test)\nprint(f\"loss start {history[0]:.3f}, end {history[-1]:.3f}\")\nprint(f\"test accuracy {accuracy:.1%}\")\n\n# --- 6. ציור: עקומת הלמידה וקו ההפרדה ---\nfig, (a1, a2) = plt.subplots(1, 2, figsize=(11, 4))\na1.plot(history); a1.set_title(\"loss\")\na2.scatter(X_train[:, 0], X_train[:, 1], c=y_train, cmap=\"coolwarm\", s=12)\nxs = np.linspace(-2.5, 2.5, 50)\na2.plot(xs, -(w[0] * xs + b) / w[1], \"k-\")   # הקו שבו z = 0\nplt.show()\n",
